namespace Reflectable { public sealed class SkillManager { readonly PlayerStats stats; readonly ExperienceManager xp; public SkillManager(PlayerStats p,ExperienceManager e){stats=p;xp=e;} public bool Upgrade(string skill){if(skill!="POWER"&&skill!="RICOCHET"&&skill!="EXTRA BALL")return false;int cost=skill=="EXTRA BALL"?5:1;if(!xp.Spend(cost))return false;switch(skill){case "POWER":stats.Power++;break;case "RICOCHET":stats.Ricochet++;break;case "EXTRA BALL":stats.ExtraBall++;break;}return true;} } }
